mapper.select:

SELECT l.id, l.biz_date, l.change_type, l.fg_doc_id AS doc_id, d.kind AS doc_kind, l.doc_no, l.warehouse_id,
       w.name AS warehouse_name, l.style_sku_id, l.change_qty, l.balance_qty, l.create_by, l.create_time
FROM fg_stock_log l
JOIN fg_doc d ON d.id = l.fg_doc_id
JOIN bas_warehouse w ON w.id = l.warehouse_id
JOIN sty_style_sku k ON k.id = l.style_sku_id
JOIN sty_style st ON st.id = k.style_id
WHERE true
AND l.warehouse_id = #{q.warehouseId}
AND l.style_sku_id = #{q.styleSkuId}
AND k.style_id = #{q.styleId}

    AND l.change_type IN #{t}

AND l.biz_date >= #{q.bizDateFrom}
AND l.biz_date <= #{q.bizDateTo}



            AND (upper(l.doc_no) IN #{c}
                 OR upper(k.code) IN #{c}
                 OR upper(st.code) IN #{c})

        AND (upper(l.doc_no) LIKE #{kw} OR upper(k.code) LIKE #{kw} OR upper(st.code) LIKE #{kw})


ORDER BY l.id DESC
